CREATE TABLE public.culture_quest_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), card_id uuid NOT NULL REFERENCES public.cultural_inspirations(id) ON DELETE CASCADE, round_number integer NOT NULL CHECK (round_number BETWEEN 1 AND 3), position integer NOT NULL CHECK (position BETWEEN 1 AND 12), prompt text NOT NULL CHECK (length(prompt) BETWEEN 1 AND 500), options jsonb NOT NULL DEFAULT '[]'::jsonb, answer integer NOT NULL DEFAULT 0 CHECK (answer BETWEEN 0 AND 3), photo_path text, challenge text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(card_id,round_number,position));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.culture_quest_items TO authenticated;
GRANT ALL ON public.culture_quest_items TO service_role;
ALTER TABLE public.culture_quest_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY quest_items_creator_read ON public.culture_quest_items FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=card_id AND c.hidden_at IS NULL AND trip_private.feature_on(c.trip_id,'inspiration') AND trip_private.is_trip_member(c.trip_id,auth.uid()) AND (c.creator_id=auth.uid() OR c.partner_id=auth.uid())));
CREATE POLICY quest_items_creator_add ON public.culture_quest_items FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=card_id AND c.hidden_at IS NULL AND trip_private.feature_on(c.trip_id,'inspiration') AND trip_private.is_trip_member(c.trip_id,auth.uid()) AND (c.creator_id=auth.uid() OR c.partner_id=auth.uid())));
CREATE POLICY quest_items_creator_edit ON public.culture_quest_items FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=card_id AND c.hidden_at IS NULL AND trip_private.feature_on(c.trip_id,'inspiration') AND trip_private.is_trip_member(c.trip_id,auth.uid()) AND (c.creator_id=auth.uid() OR c.partner_id=auth.uid()))) WITH CHECK (EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=card_id AND c.hidden_at IS NULL AND trip_private.feature_on(c.trip_id,'inspiration') AND trip_private.is_trip_member(c.trip_id,auth.uid()) AND (c.creator_id=auth.uid() OR c.partner_id=auth.uid())));
CREATE POLICY quest_items_creator_remove ON public.culture_quest_items FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=card_id AND c.hidden_at IS NULL AND trip_private.feature_on(c.trip_id,'inspiration') AND trip_private.is_trip_member(c.trip_id,auth.uid()) AND (c.creator_id=auth.uid() OR c.partner_id=auth.uid())));
CREATE OR REPLACE FUNCTION trip_private.quest_item_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.card_id<>OLD.card_id THEN RAISE EXCEPTION 'Quest ownership cannot change'; END IF; IF jsonb_typeof(NEW.options)<>'array' OR jsonb_array_length(NEW.options)<>4 OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.options) x WHERE jsonb_typeof(x)<>'string' OR length(x #>> '{}')>150) THEN RAISE EXCEPTION 'Add four short choices'; END IF; IF NEW.round_number=2 AND (NEW.photo_path IS NULL OR NOT EXISTS(SELECT 1 FROM public.cultural_inspirations c WHERE c.id=NEW.card_id AND c.photo_path=NEW.photo_path)) THEN RAISE EXCEPTION 'Picture It uses your uploaded photo'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER culture_quest_item_guard BEFORE INSERT OR UPDATE ON public.culture_quest_items FOR EACH ROW EXECUTE FUNCTION trip_private.quest_item_guard();
REVOKE ALL ON FUNCTION trip_private.quest_item_guard() FROM PUBLIC, anon, authenticated;
CREATE TABLE public.culture_quest_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), card_id uuid NOT NULL REFERENCES public.cultural_inspirations(id) ON DELETE CASCADE, host_id uuid NOT NULL, code text UNIQUE, team_count integer NOT NULL DEFAULT 0 CHECK (team_count BETWEEN 0 AND 3), position integer NOT NULL DEFAULT 1, revealed boolean NOT NULL DEFAULT false, finished_at timestamptz, expires_at timestamptz NOT NULL DEFAULT (now()+interval '24 hours'), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.culture_quest_sessions TO authenticated;
GRANT ALL ON public.culture_quest_sessions TO service_role;
ALTER TABLE public.culture_quest_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.culture_quest_players (session_id uuid NOT NULL REFERENCES public.culture_quest_sessions(id) ON DELETE CASCADE, user_id uuid NOT NULL, team_number integer, score integer NOT NULL DEFAULT 0, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(session_id,user_id));
GRANT SELECT ON public.culture_quest_players TO authenticated;
GRANT ALL ON public.culture_quest_players TO service_role;
ALTER TABLE public.culture_quest_players ENABLE ROW LEVEL SECURITY;
CREATE POLICY quest_session_member ON public.culture_quest_sessions FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.culture_quest_players p WHERE p.session_id=id AND p.user_id=auth.uid()));
CREATE POLICY quest_player_member ON public.culture_quest_players FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.culture_quest_answers (session_id uuid NOT NULL REFERENCES public.culture_quest_sessions(id) ON DELETE CASCADE, item_id uuid NOT NULL REFERENCES public.culture_quest_items(id) ON DELETE CASCADE, user_id uuid NOT NULL, choice integer NOT NULL CHECK(choice BETWEEN 0 AND 3), confirmed boolean NOT NULL DEFAULT false, awarded integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(session_id,item_id,user_id));
GRANT SELECT ON public.culture_quest_answers TO authenticated;
GRANT ALL ON public.culture_quest_answers TO service_role;
ALTER TABLE public.culture_quest_answers ENABLE ROW LEVEL SECURITY;
CREATE POLICY quest_answers_own ON public.culture_quest_answers FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.culture_stamps (user_id uuid NOT NULL, card_id uuid NOT NULL REFERENCES public.cultural_inspirations(id) ON DELETE CASCADE, title text NOT NULL, points integer NOT NULL DEFAULT 0, champion boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,card_id));
GRANT SELECT ON public.culture_stamps TO authenticated;
GRANT ALL ON public.culture_stamps TO service_role;
ALTER TABLE public.culture_stamps ENABLE ROW LEVEL SECURITY;
CREATE POLICY culture_stamps_own ON public.culture_stamps FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE OR REPLACE FUNCTION trip_private.quest_access(p_card uuid,p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.cultural_inspirations c WHERE c.id=p_card AND c.hidden_at IS NULL AND c.reveal_on<=CURRENT_DATE AND trip_private.feature_on(c.trip_id,'inspiration') AND trip_private.is_trip_member(c.trip_id,p_user)) $$;
REVOKE ALL ON FUNCTION trip_private.quest_access(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION trip_private.quest_access(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.culture_quest(p_action text,p_session uuid DEFAULT NULL,p_card uuid DEFAULT NULL,p_code text DEFAULT NULL,p_item uuid DEFAULT NULL,p_choice integer DEFAULT NULL,p_teams integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.culture_quest_sessions%ROWTYPE; c public.cultural_inspirations%ROWTYPE; it public.culture_quest_items%ROWTYPE; total integer; n integer; answer_count integer; payload jsonb; pinteger integer; reward integer; v_code text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
IF p_action='start' THEN SELECT * INTO c FROM public.cultural_inspirations WHERE id=p_card; IF NOT FOUND OR NOT trip_private.quest_access(p_card,auth.uid()) THEN RAISE EXCEPTION 'Quest unavailable'; END IF; SELECT count(*) INTO total FROM public.culture_quest_items WHERE card_id=p_card; IF total<3 OR NOT EXISTS(SELECT 1 FROM public.culture_quest_items WHERE card_id=p_card AND round_number=1) OR NOT EXISTS(SELECT 1 FROM public.culture_quest_items WHERE card_id=p_card AND round_number=2) OR NOT EXISTS(SELECT 1 FROM public.culture_quest_items WHERE card_id=p_card AND round_number=3) THEN RAISE EXCEPTION 'Finish all three rounds first'; END IF; IF p_teams NOT BETWEEN 0 AND 3 OR p_teams=1 THEN RAISE EXCEPTION 'Choose solo, two or three teams'; END IF; IF p_teams>0 THEN FOR n IN 1..8 LOOP v_code:=upper(substr(encode(gen_random_bytes(5),'hex'),1,6)); EXIT WHEN NOT EXISTS(SELECT 1 FROM public.culture_quest_sessions WHERE code=v_code); END LOOP; IF EXISTS(SELECT 1 FROM public.culture_quest_sessions WHERE code=v_code) THEN RAISE EXCEPTION 'Try again'; END IF; END IF; INSERT INTO public.culture_quest_sessions(card_id,host_id,code,team_count) VALUES(p_card,auth.uid(),v_code,p_teams) RETURNING * INTO s; INSERT INTO public.culture_quest_players(session_id,user_id,team_number) VALUES(s.id,auth.uid(),CASE WHEN p_teams>0 THEN 1 ELSE NULL END); p_session:=s.id;
ELSIF p_action='join' THEN SELECT * INTO s FROM public.culture_quest_sessions WHERE code=upper(trim(p_code)) AND code IS NOT NULL AND expires_at>now() AND finished_at IS NULL FOR UPDATE; IF NOT FOUND OR NOT trip_private.quest_access(s.card_id,auth.uid()) THEN RAISE EXCEPTION 'Quest code unavailable'; END IF; SELECT count(*) INTO n FROM public.culture_quest_players WHERE session_id=s.id; IF n>=6 AND NOT EXISTS(SELECT 1 FROM public.culture_quest_players WHERE session_id=s.id AND user_id=auth.uid()) THEN RAISE EXCEPTION 'This quest is full'; END IF; INSERT INTO public.culture_quest_players(session_id,user_id,team_number) VALUES(s.id,auth.uid(),CASE WHEN s.team_count>0 THEN (n%s.team_count)+1 ELSE NULL END) ON CONFLICT DO NOTHING; p_session:=s.id;
END IF;
SELECT * INTO s FROM public.culture_quest_sessions WHERE id=p_session FOR UPDATE; IF NOT FOUND OR NOT trip_private.quest_access(s.card_id,auth.uid()) OR NOT EXISTS(SELECT 1 FROM public.culture_quest_players WHERE session_id=s.id AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Quest unavailable'; END IF;
SELECT * INTO it FROM public.culture_quest_items WHERE card_id=s.card_id ORDER BY round_number,position LIMIT 1 OFFSET s.position-1; SELECT count(*) INTO total FROM public.culture_quest_items WHERE card_id=s.card_id;
IF p_action='answer' THEN IF s.finished_at IS NOT NULL OR s.revealed OR it.id IS DISTINCT FROM p_item OR p_choice NOT BETWEEN 0 AND 3 THEN RAISE EXCEPTION 'This question is closed'; END IF; INSERT INTO public.culture_quest_answers(session_id,item_id,user_id,choice) VALUES(s.id,it.id,auth.uid(),p_choice) ON CONFLICT DO NOTHING;
ELSIF p_action='reveal' THEN IF s.host_id<>auth.uid() OR s.finished_at IS NOT NULL OR s.revealed OR it.id IS NULL THEN RAISE EXCEPTION 'Host only'; END IF; UPDATE public.culture_quest_answers SET awarded=CASE WHEN choice=it.answer THEN 10 ELSE 0 END WHERE session_id=s.id AND item_id=it.id; UPDATE public.culture_quest_players p SET score=(SELECT coalesce(sum(a.awarded),0) FROM public.culture_quest_answers a WHERE a.session_id=s.id AND a.user_id=p.user_id) WHERE p.session_id=s.id; UPDATE public.culture_quest_sessions SET revealed=true,updated_at=now() WHERE id=s.id; s.revealed:=true;
ELSIF p_action='next' THEN IF s.host_id<>auth.uid() OR NOT s.revealed OR s.finished_at IS NOT NULL THEN RAISE EXCEPTION 'Reveal this question first'; END IF; IF s.position>=total THEN UPDATE public.culture_quest_sessions SET finished_at=now(),updated_at=now() WHERE id=s.id; UPDATE public.culture_quest_players SET completed_at=now() WHERE session_id=s.id; INSERT INTO public.culture_stamps(user_id,card_id,title,points,champion) SELECT p.user_id,s.card_id, CASE WHEN c.category='Language' THEN 'Spoke ' ELSE 'Tasted ' END || c.title,p.score,p.score=(SELECT max(score) FROM public.culture_quest_players WHERE session_id=s.id) FROM public.culture_quest_players p CROSS JOIN public.cultural_inspirations c WHERE p.session_id=s.id AND c.id=s.card_id ON CONFLICT(user_id,card_id) DO UPDATE SET points=GREATEST(culture_stamps.points,EXCLUDED.points),champion=culture_stamps.champion OR EXCLUDED.champion,updated_at=now(); ELSE UPDATE public.culture_quest_sessions SET position=position+1,revealed=false,updated_at=now() WHERE id=s.id; END IF;
ELSIF p_action NOT IN ('state','start','join') THEN RAISE EXCEPTION 'Unknown quest action'; END IF;
SELECT * INTO s FROM public.culture_quest_sessions WHERE id=p_session; SELECT * INTO it FROM public.culture_quest_items WHERE card_id=s.card_id ORDER BY round_number,position LIMIT 1 OFFSET s.position-1; SELECT count(*) INTO answer_count FROM public.culture_quest_answers WHERE session_id=s.id AND item_id=it.id; SELECT jsonb_agg(jsonb_build_object('user_id',p.user_id,'score',p.score,'team',p.team_number) ORDER BY p.score DESC) INTO payload FROM public.culture_quest_players p WHERE p.session_id=s.id;
RETURN jsonb_build_object('session',s.id,'code',s.code,'host',s.host_id,'position',s.position,'total',total,'revealed',s.revealed,'finished',s.finished_at IS NOT NULL,'answerCount',answer_count,'players',coalesce(payload,'[]'::jsonb),'item',CASE WHEN it.id IS NULL THEN NULL ELSE jsonb_build_object('id',it.id,'round',it.round_number,'prompt',it.prompt,'options',it.options,'photo_path',it.photo_path,'challenge',it.challenge,'answer',CASE WHEN s.revealed OR s.finished_at IS NOT NULL THEN it.answer ELSE NULL END) END,'myAnswer',(SELECT a.choice FROM public.culture_quest_answers a WHERE a.session_id=s.id AND a.item_id=it.id AND a.user_id=auth.uid()),'experience',CASE WHEN s.finished_at IS NOT NULL THEN (SELECT jsonb_build_object('title',x.title,'backstory',x.backstory,'steps',x.steps,'meaning',x.meaning,'needs',x.needs) FROM public.cultural_inspirations x WHERE x.id=s.card_id) ELSE NULL END);
END $$;
REVOKE ALL ON FUNCTION public.culture_quest(text,uuid,uuid,text,uuid,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.culture_quest(text,uuid,uuid,text,uuid,integer,integer) TO authenticated;